<?php
/** Compatibility fixtures explicitly represent owner-reviewed ORIGINAL TEST records.
 * This helper is outside the plugin ZIP. It does not approve real data or test the
 * new approval workflow; v04-studio.php separately exercises that workflow.
 */
function baseline_review_fixture($qid,$fixture_occ=null){
    if(!class_exists('CAFCC_Studio'))return;global $wpdb;$q=CAFCC_Repository::get('questions',$qid);if(!$q||$q['publication_status']!=='published'||$q['verification_status']!=='verified')return;
    $doc=CAFCC_Repository::get('documents',$q['document_id']);if(!$doc)return;$meta=CAFCC_Academic::get('questions',$qid);$ot=CAFCC_DB::table('occurrences');$all_occ=$wpdb->get_results($wpdb->prepare("SELECT * FROM $ot WHERE question_id=%d ORDER BY id",$qid),ARRAY_A);if($fixture_occ===null&&count($all_occ)>1){foreach($all_occ as $test_occ)baseline_review_fixture($qid,$test_occ);return;}$occ=$fixture_occ??($all_occ[0]??null);$at=CAFCC_DB::table('answers');$answers=$wpdb->get_col($wpdb->prepare("SELECT id FROM $at WHERE question_id=%d AND publication_status='published' AND review_status='verified'",$qid));
    $sid='TEST-BASELINE-'.$qid.($occ?'-O'.$occ['id']:'');$hash=hash('sha256','TEST ORIGINAL fixture source '.$doc['id'].' Q'.$qid.' O'.($occ['id']??0));$sub=CAFCC_Repository::get('subjects',CAFCC_Repository::get('chapters',$q['chapter_id'])['subject_id']);
    $data=CAFCC_Studio::clean(array('stable_id'=>$sid,'source_hash'=>$hash,'source_key'=>'TEST-BASELINE-DOC-'.$doc['id'],'subject_code'=>$sub['code'],'source_type'=>$doc['source_type'],'exam_attempt'=>$doc['exam_attempt'],'mtp_series'=>$doc['source_type']==='mtp'?'TEST':'','section'=>'TEST ORIGINAL','question_format'=>($meta['question_type']??'')==='mcq'?'mcq':'subjective','question_type'=>$meta['question_type']??'unknown','reference'=>$q['question_number'],'subreference'=>$occ['subquestion_number']??'','official_url'=>$doc['official_url'],'scheme'=>'TEST ORIGINAL','edition_id'=>$meta['edition_id']??null,'classification'=>array(),'rights_mode'=>'original','rights_basis'=>'TEST ORIGINAL fixture, explicitly reviewed by test administrator.','question_page'=>'TEST page 1','question_coordinates'=>array('start'=>array(1,1),'end'=>array(2,2)),'answer'=>array('source_hash'=>$hash,'official_url'=>$doc['official_url'],'reference'=>$q['question_number'],'subreference'=>$occ['subquestion_number']??'','page'=>'TEST page 1','question_identity'=>$sid,'question_reference'=>$q['question_number'],'question_subreference'=>$occ['subquestion_number']??'','answer_ids'=>array_map('intval',$answers))));
    if(is_wp_error($data))throw new RuntimeException($data->get_error_message());$table=CAFCC_Studio::table();$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE stable_id=%s",$sid),ARRAY_A);$row=array('data'=>$data,'question_id'=>$qid,'occurrence_id'=>$occ['id']??null);$a=array();foreach(CAFCC_Studio::STAGES as $stage)$a[$stage]=array('fingerprint'=>CAFCC_Studio::fingerprint($row,$stage),'reviewer'=>get_current_user_id(),'timestamp'=>current_time('mysql',true),'reviewed_revision'=>1);$a['publication']=array('reviewer'=>get_current_user_id(),'timestamp'=>current_time('mysql',true));
    $values=array('question_format'=>$data['question_format'],'stable_id'=>$sid,'question_id'=>$qid,'occurrence_id'=>$occ['id']??null,'source_hash'=>$hash,'source_identity'=>hash('sha256',$hash.'|TEST ORIGINAL|'.$q['question_number'].'|'.$data['subreference']),'source_key'=>$data['source_key'],'subject_code'=>$sub['code'],'source_type'=>$doc['source_type'],'exam_attempt'=>$doc['exam_attempt'],'mtp_series'=>$data['mtp_series'],'section_label'=>'TEST ORIGINAL','question_number'=>$q['question_number'],'subquestion_number'=>$data['subreference'],'fulltext_allowed'=>1,'question_content_id'=>$a['question_revision']?($row_q= $wpdb->get_row($wpdb->prepare("SELECT id,revision FROM ".CAFCC_Practice::table('content')." WHERE question_id=%d AND content_kind='question'",$qid),ARRAY_A))['id']??0:0,'question_content_revision'=>$row_q['revision']??0,'answer_content_id'=>($row_a=$wpdb->get_row($wpdb->prepare("SELECT id,revision FROM ".CAFCC_Practice::table('content')." WHERE question_id=%d AND content_kind='answer'",$qid),ARRAY_A))['id']??0,'answer_content_revision'=>$row_a['revision']??0,'revision'=>$old?(int)$old['revision']+1:1,'status'=>'approved','publication_status'=>'published','payload'=>wp_json_encode($data),'payload_hash'=>hash('sha256',wp_json_encode($data)),'approvals'=>wp_json_encode($a),'batch_key'=>'TEST-BASELINE-OWNER-FIXTURES','modified_at'=>current_time('mysql',true));
    if($old)$wpdb->update($table,$values,array('id'=>$old['id']));else $wpdb->insert($table,$values);
}
function baseline_after_record($kind,$record){
    if(!class_exists('CAFCC_Studio')||!is_array($record))return;
    if($kind==='questions')baseline_review_fixture($record['id']);elseif(in_array($kind,array('tags','occurrences','answers','subject_tags'),true))baseline_review_fixture($record['question_id']);elseif($kind==='documents'){global $wpdb;$t=CAFCC_DB::table('questions');foreach($wpdb->get_col($wpdb->prepare("SELECT id FROM $t WHERE document_id=%d",$record['id'])) as $qid)baseline_review_fixture($qid);}
}
